codeExamples.tech1Snippet:
type Product = {
  id: string;
  name: string;
  categoryId: string;
  active: boolean;
  priceCents: number;
};

export function listProducts(
  products: Product[],
  categoryId: string,
): Product[] {
  return products
    .filter((product) => product.active && product.categoryId === categoryId)
    .sort((left, right) => left.name.localeCompare(right.name));
}

